package ir.orix.school.assessment.application;
import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
import ir.orix.school.assessment.domain.Assessment; import ir.orix.school.assessment.persistence.*; import ir.orix.school.classroom.domain.ClassInstructor; import ir.orix.school.classroom.persistence.ClassInstructorRepository; import ir.orix.school.organization.domain.TenantMembership; import ir.orix.school.organization.persistence.TenantMembershipRepository; import ir.orix.school.people.domain.InstructorProfile; import ir.orix.school.people.persistence.InstructorProfileRepository; import ir.orix.school.shared.security.ScopeAuthorizer; import ir.orix.school.shared.web.ApiException;
@Component public class AssessmentAccessGuard {
 private final AssessmentRepository assessments; private final AssessmentTargetRepository targets; private final TenantMembershipRepository memberships; private final InstructorProfileRepository instructors; private final ClassInstructorRepository classInstructors; private final ScopeAuthorizer authorizer;
 public AssessmentAccessGuard(AssessmentRepository assessments,AssessmentTargetRepository targets,TenantMembershipRepository memberships,InstructorProfileRepository instructors,ClassInstructorRepository classInstructors,ScopeAuthorizer authorizer){this.assessments=assessments;this.targets=targets;this.memberships=memberships;this.instructors=instructors;this.classInstructors=classInstructors;this.authorizer=authorizer;}
 @Transactional(readOnly=true) public void require(Long tenantId,Long membershipId,Long accountId,Long assessmentId,String permission){Assessment assessment=assessments.findByIdAndTenantId(assessmentId,tenantId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"ASSESSMENT_NOT_FOUND","The requested assessment was not found."));if(authorizer.isTenantAdmin()||(assessment.getCreatedBy()!=null&&assessment.getCreatedBy().getId().equals(accountId)))return;TenantMembership membership=memberships.findByIdAndTenantId(membershipId,tenantId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"MEMBERSHIP_NOT_FOUND","Membership was not found."));Optional<InstructorProfile> instructor=instructors.findByTenantIdAndPersonId(tenantId,membership.getPerson().getId());boolean allowed=targets.findAllByAssessmentId(assessmentId).stream().anyMatch(t->instructor.isPresent()?classInstructors.existsByClassSectionIdAndInstructorIdAndStatus(t.getClassSection().getId(),instructor.get().getId(),ClassInstructor.Status.ACTIVE):authorizer.hasPermissionForBranch(permission,t.getClassSection().getOffering().getBranch().getId()));if(!allowed)throw new ApiException(HttpStatus.FORBIDDEN,"ASSESSMENT_ACCESS_DENIED","You are not authorized for this assessment.");}
}
